503	\section{Finiteness via \(\mathbb{P}^1\)}
504	\label{sec:RiemannRoch_Adelic_finiteness}
505	
506	By \Cref{thm:adelic_HModuleOne_linearEquiv_cokernel}, it remains to prove
507	that \(A_{01}/(A_0+A_1)\) is finite-dimensional.  We pull back the two
508	standard charts of \(\mathbb P^1\) along a finite morphism.
509	
510	\begin{proposition}
511	[A finite map to \(\mathbb{P}^1\), from a nonconstant map (N9)]
512	  \label{thm:adelic_exists_finiteMorphismToP1}
513	  \leanok
514	  \lean{AlgebraicGeometry.Adelic.hasFiniteMapToP1_of_existsNonconstantMapToP1}
515	  \uses{def:adelic_nonconstant_map_gate, thm:adelic_nonconstant_map_isFinite}
516	  % [papaioannou] Cor. 1.7-1.8 (a transcendental x has finitely many zeros/poles; [F:K(x)] finite); [cff] Thm. 12.6
517	  \source{papaioannou-algebraic-rr, cff-curves-function-fields}
518	  Under the gate \(\mathrm{ExistsNonconstantMapToP1}\, C\)
519	  (\Cref{def:adelic_nonconstant_map_gate}: a nonconstant \(k\)-morphism
520	  \(\pi \colon C \to \mathbb{P}^1_k\) exists), \(\pi\) is automatically
521	  a \emph{finite} morphism; equivalently, the finite-map gate
522	  \(\mathrm{HasFiniteMapToP1}\, C\) holds.
523	\end{proposition}
524	\begin{proof}
525	  \leanok
526	  Let \(\pi \colon C \to \mathbb{P}^1_k\) be a nonconstant \(k\)-morphism
527	  (\Cref{def:adelic_nonconstant_map_gate}), with \(\pi(x_1) \ne
528	  \pi(x_2)\) for some \(x_1, x_2 \in C\). Since \(\mathbb{P}^1_k\) is
529	  separated and of finite type over \(k\), \Cref{thm:adelic_nonconstant_map_isFinite}
530	  applied to \(\pi\) shows \(\pi\) is a finite morphism.
531	\end{proof}
532	
533	\begin{definition}
534	[Gate: a nonconstant map to \(\mathbb{P}^1\) (N9a)]
535	  \label{def:adelic_nonconstant_map_gate}
536	  \notready  % gate class AlgebraicGeometry.Adelic.ExistsNonconstantMapToP1, no instance
537	  \lean{AlgebraicGeometry.Adelic.ExistsNonconstantMapToP1}
538	  \uses{def:projective_space}
539	  The class \(\mathrm{ExistsNonconstantMapToP1}\, C\) asserts the
540	  existence of a \(k\)-morphism \(\pi \colon C \to \mathbb{P}^1_k\)
541	  taking two distinct values \(\pi(x_1) \ne \pi(x_2)\). This is the
542	  honest remaining kernel of the finite-map gate: any nonconstant
543	  rational function on \(C\) (which exists since \(K/k\) has
544	  transcendence degree one) extends to such a \(\pi\) by the valuative
545	  property of the dimension-one regular local rings of \(C\)
546	  (\Cref{lem:adelic_curve_stalk_dim_le_one}); no instance is supplied
547	  here. This gate is further reduced, decoupling it from all over-\(k\)
548	  and relative-projective-space bookkeeping, to the strictly cleaner
549	  gate \(\mathrm{ExistsNonconstantMapToProjInt}\, C\)
550	  (\Cref{def:adelic_nonconstant_projint_gate} and
551	  \cref{lem:adelic_nonconstant_projint_bridge}).
552	\end{definition}
553	
554	\begin{definition}
555	[Gate: a nonconstant map to the integral model of \(\mathbb{P}^1\)]
556	  \label{def:adelic_nonconstant_projint_gate}
557	  \notready  % gate class AlgebraicGeometry.Adelic.ExistsNonconstantMapToProjInt, no instance
558	  \lean{AlgebraicGeometry.Adelic.ExistsNonconstantMapToProjInt}
559	  The class \(\mathrm{ExistsNonconstantMapToProjInt}\, C\) asserts the
560	  existence of a scheme morphism \(f \colon C \to \operatorname{Proj}
561	  \mathbb{Z}[X_0, X_1]\) into the integral projective-line model with
562	  two distinct point-images \(f(x_1) \ne f(x_2)\) (no over-\(k\)
563	  structure required). This is the genuine one-dimensional curve
564	  content of \(\mathrm{ExistsNonconstantMapToP1}\): a nonconstant
565	  rational function of \(K\) spreads out to a rational map
566	  \(C \dashrightarrow \operatorname{Proj} \mathbb{Z}[X_0, X_1]\) which
567	  extends to an everywhere-defined morphism by the valuative criterion
568	  applied at the codimension-one (DVR) stalks of \(C\). Discharging it
569	  is currently blocked on (i) the codimension-\(\ge 2\)
570	  indeterminacy-locus extension over an \emph{arbitrary} base field
571	  \(k\) (the present smooth \(\Rightarrow\) regular \(\Rightarrow\) DVR
572	  pipeline only covers algebraically closed \(k\)) and (ii) the
573	  chart-ring identification \(\mathrm{Away}\,\mathcal A\,X_0 \cong
574	  \mathbb{Z}[X_1/X_0]\) needed to write down the resulting \(K\)-point
575	  of \(\operatorname{Proj}\mathbb{Z}[X_0,X_1]\) concretely
576	  (\Cref{thm:adelic_span_p1CoordAway_pow_top} supplies the
577	  \(\mathbb{Z}\)-span core of this identification; the base-change to
578	  \(k\) remains open). No instance is supplied here.
579	\end{definition}
580	
581	\begin{proposition}
582	[Bridge: a nonconstant map to the integral model gives one to \(\mathbb{P}^1_k\)]
583	  \label{lem:adelic_nonconstant_projint_bridge}
584	  \leanok
585	  \lean{AlgebraicGeometry.Adelic.existsNonconstantMapToP1_of_nonconstantMapToProjInt,
586	    AlgebraicGeometry.Adelic.existsNonconstantMapToP1_of_existsNonconstantMapToProjInt}
587	  \uses{def:adelic_nonconstant_projint_gate, def:adelic_nonconstant_map_gate}
588	  \(\mathrm{ExistsNonconstantMapToProjInt}\, C\) implies
589	  \(\mathrm{ExistsNonconstantMapToP1}\, C\).
590	\end{proposition}
591	\begin{proof}
592	  \leanok
593	  The concrete \(\mathbb{P}^1_k = \mathbb{P}(\mathrm{ULift}(\mathrm{Fin}\,
594	  2); \operatorname{Spec} k)\) is, by construction, the fibre product
595	  \(\operatorname{Spec} k \times_{\top} \operatorname{Proj}
596	  \mathbb{Z}[X_0, X_1]\) over the \emph{terminal} scheme \(\top\). Since
597	  any two morphisms into \(\top\) agree, the compatibility square
598	  required by the universal property of this pullback is automatic:
599	  given \(f \colon C \to \operatorname{Proj} \mathbb{Z}[X_0, X_1]\) and
600	  the ambient structure map \(C \to \operatorname{Spec} k\), the two
601	  assemble into a unique \(g \colon C \to \mathbb{P}^1_k\) with
602	  \(g\) over \(\operatorname{Spec} k\) and \(g\) composed with the
603	  projection \(\mathbb{P}^1_k \to \operatorname{Proj} \mathbb{Z}[X_0,
604	  X_1]\) equal to \(f\). If \(f(x_1) \ne f(x_2)\) then, composing with
605	  the projection, \(g(x_1) \ne g(x_2)\); hence \(g\) is a nonconstant
606	  \(k\)-morphism \(C \to \mathbb{P}^1_k\).
607	\end{proof}
