609	\begin{lemma}
610	[Quasi-finite algebras do not raise Krull dimension]
611	  \label{lem:adelic_quasiFinite_dim_le}
612	  \leanok
613	  \lean{AlgebraicGeometry.Adelic.ringKrullDim_le_of_quasiFinite}
614	  For a quasi-finite \(R\)-algebra \(A\), \(\operatorname{ringKrullDim}
615	  A \le \operatorname{ringKrullDim} R\).
616	\end{lemma}
617	\begin{proof}
618	  \leanok
619	  Quasi-finiteness gives incomparability of primes over the contraction
620	  map \(\operatorname{Spec} A \to \operatorname{Spec} R\): if two primes
621	  of \(A\) contract to the same prime of \(R\) and one is contained in
622	  the other, they are equal. Hence the contraction map is strictly
623	  monotone on chains of primes, so it strictly increases no chain
624	  length in the wrong direction and \(\operatorname{ringKrullDim} A \le
625	  \operatorname{ringKrullDim} R\).
626	\end{proof}
