628	\begin{lemma}
629	[Dimension one for standard-smooth curves]
630	  \label{lem:adelic_relDimOne_dim_le_one}
631	  \leanok
632	  \lean{AlgebraicGeometry.Adelic.ringKrullDim_le_one_of_isStandardSmoothOfRelativeDimension_one}
633	  \uses{lem:adelic_quasiFinite_dim_le}
634	  Let \(S\) be standard-smooth of relative dimension \(1\) over a field
635	  \(k\), and let \(q\) be a prime of \(S\). Every localisation \(S_q\)
636	  of \(S\) at \(q\) satisfies \(\operatorname{ringKrullDim} S_q \le 1\).
637	\end{lemma}
638	\begin{proof}
639	  \leanok
640	  Standard smoothness of relative dimension one makes \(\Omega_{S/k}\)
641	  free of rank one; writing the spanning vector as a finite combination
642	  of exact differentials, some \(dt\) (for a generator \(t\) of \(S\))
643	  has coefficient \(a \notin q\) in this basis. Over \(S_q\) the element
644	  \(a\) is a unit, so \(dt\) spans \(\Omega_{S_q/k}\); the \(k\)-algebra
645	  map \(k[X] \to S_q\), \(X \mapsto t\), then makes \(S_q\) formally
646	  unramified over \(k[X]\) (\(\Omega_{S_q/k[X]} = 0\)) and essentially
647	  of finite type, i.e.\ \emph{quasi-finite} over \(k[X]\). Since
648	  \(k[X]\) is a PID, \(\operatorname{ringKrullDim} k[X] = 1\), and
649	  \Cref{lem:adelic_quasiFinite_dim_le} gives
650	  \(\operatorname{ringKrullDim} S_q \le 1\).
651	\end{proof}
