653	\begin{lemma}
654	[Stalks of the curve have dimension \(\le 1\)]
655	  \label{lem:adelic_curve_stalk_dim_le_one}
656	  \leanok
657	  \lean{AlgebraicGeometry.Adelic.ringKrullDim_stalk_le_one_of_curve}
658	  \uses{lem:adelic_relDimOne_dim_le_one}
659	  Every stalk \(\struct{C, z}\) of the curve \(C\) (smooth of relative
660	  dimension one over \(\operatorname{Spec} k\)) has
661	  \(\operatorname{ringKrullDim} \struct{C, z} \le 1\).
662	\end{lemma}
663	\begin{proof}
664	  \leanok
665	  As \(\operatorname{Spec} k\) is a single point, \(z\) has a standard
666	  smooth chart \(V\) of relative dimension one over all of
667	  \(\operatorname{Spec} k\); the stalk \(\struct{C, z}\) is the
668	  localisation of \(\Gamma(V, \struct{C})\) at the prime of \(z\), so
669	  \Cref{lem:adelic_relDimOne_dim_le_one} applies directly.
670	\end{proof}
