672	\begin{lemma}
673	[Coheight \(\le 1\) on the curve]
674	  \label{lem:adelic_curve_coheight_le_one}
675	  \leanok
676	  \lean{AlgebraicGeometry.Adelic.coheight_le_one_of_curve}
677	  \uses{lem:adelic_curve_stalk_dim_le_one, thm:ringKrullDim_stalk_eq_coheight}
678	  Every point \(z\) of \(C\) has topological coheight
679	  \(\operatorname{coheight} z \le 1\).
680	\end{lemma}
681	\begin{proof}
682	  \leanok
683	  Immediate from \Cref{lem:adelic_curve_stalk_dim_le_one} and the
684	  stalk--coheight bridge \Cref{thm:ringKrullDim_stalk_eq_coheight}
685	  (\(\operatorname{coheight} z = \operatorname{ringKrullDim}
686	  \struct{C, z}\)).
687	\end{proof}
