689	\begin{lemma}
690	[Non-generic points of the curve are closed]
691	  \label{lem:adelic_nongeneric_closed}
692	  \leanok
693	  \lean{AlgebraicGeometry.Adelic.isClosed_singleton_of_coheight_le_one}
694	  \uses{lem:adelic_curve_coheight_le_one}
695	  On an irreducible scheme all of whose points have coheight \(\le 1\),
696	  every point \(z\) other than the generic point is closed.
697	\end{lemma}
698	\begin{proof}
699	  \leanok
700	  If \(\{z\}\) were not closed, its closure would contain a point
701	  \(z' \ne z\) with \(z \rightsquigarrow z'\), giving a strict
702	  specialisation chain \(z' \prec z \prec \eta\) (\(\eta\) the generic
703	  point, since \(z \ne \eta\)); each strict step adds at least one to
704	  coheight, so \(\operatorname{coheight} z' \ge 2\), contradicting the
705	  hypothesis.
706	\end{proof}
