\begin{theorem}
[The twist-ledger alternating dimension identity]
  \label{thm:adelic_ledger_alternating}
  \leanok
  \lean{AlgebraicGeometry.Adelic.ledger_alternating}
  \uses{lem:adelic_finrank_alternating_exact4, thm:adelic_windowMap_injective, def:adelic_chi_ledger, thm:adelic_twist_exact_sequence}
  Given the full four-term ledger exact sequence of
  \Cref{thm:adelic_twist_exact_sequence} (with the connecting map and
  the surjectivity at \(\check{H}^1(D')\) supplied as an explicit
  hypothesis, as noted there) between finite-dimensional \(k\)-vector
  spaces,
  \[
    \dim_k\bigl(L(D')/L(D)\bigr) - \dim_k\bigl(\Gamma(V,\struct{C}(D'))/
      \Gamma(V,\struct{C}(D))\bigr) + h^1(D) - h^1(D') = 0.
  \]
\end{theorem}
\begin{proof}
  \leanok
  \Cref{lem:adelic_finrank_alternating_exact4} applied to the four-term
  sequence, whose injectivity at the left is
  \Cref{thm:adelic_windowMap_injective}.
\end{proof}

\begin{theorem}
[One-step \(\chi\)-additivity]
  \label{thm:adelic_chi_additivity}
  \leanok
  \lean{AlgebraicGeometry.Adelic.chi_add}
  \uses{thm:adelic_ledger_alternating, thm:adelic_dim_adele_quotient_eq_degree}
  Under the hypotheses of \Cref{thm:adelic_ledger_alternating} for
  \(D \le D'\),
  \[
    \chi(D') \;=\; \chi(D) + \dim_k\bigl(\Gamma(V,\struct{C}(D'))/
      \Gamma(V,\struct{C}(D))\bigr).
  \]
  Combined with \Cref{thm:adelic_dim_adele_quotient_eq_degree}, for a
  one-point bump \(D' = D + P\) this is \(\chi(D+P) = \chi(D) + \deg P\).
\end{theorem}
\begin{proof}
  \leanok
  Rank--nullity identifies
  \(\dim_k\bigl(\Gamma(\top,\struct{C}(D'))/\Gamma(\top,\struct{C}(D))\bigr)
  = \ell(D') - \ell(D)\); substituting into
  \Cref{thm:adelic_ledger_alternating} and rearranging with
  \(\chi = \ell - h^1\) gives the claim.
\end{proof}

\begin{theorem}
[\(\chi\)-KEYSTONE: \(\chi(D) = \deg D + 1 - g\)]
  \label{thm:adelic_chi_eq_chi_zero_add_degree}
  \uses{thm:adelic_chi_additivity, thm:adelic_module_finite_genus, def:genus, inst:Scheme_instIsHModuleHomFinite_toModuleKSheaf}
  % [papaioannou] Thm. 1.18 (dim D = deg D + 1 - g + i(D)); [cff] Cor. 12.11, Thm. 14.1
  \source{papaioannou-algebraic-rr, cff-curves-function-fields}
  The Euler characteristic \(\chi(D) = \ell(D) - i(D)\) is additive in the

  bound \(v_P(f) \ge -D(P)\) at every prime divisor \(P\): on \(V\) this
  is the hypothesis \(f \in \Gamma(V, \struct{C}(D))\), and off \(V\) it
  is the bound \(v_P(f) \ge -D'(P) = -D(P)\) (using \(D = D'\) off
  \(V\)) already known from \(f \in L(D')\).
\end{proof}

\begin{definition}
[The cover cohomology and the window map]
  \label{def:adelic_H1_window}
  \leanok
  \lean{AlgebraicGeometry.Adelic.H1, AlgebraicGeometry.Adelic.H1Twist,
    AlgebraicGeometry.Adelic.windowMap}
  \uses{def:adelic_coboundary, lem:adelic_coboundary_le_overlap}
  The \emph{cover cohomology} \(\check{H}^1(D) = \Gamma(V,
  \struct{C}(D))/B(D)\) (\(B(D) \subseteq \Gamma(V, \struct{C}(D))\) by
  \Cref{lem:adelic_coboundary_le_overlap}). For \(D \le D'\), the
  inclusions \(\Gamma(V, \struct{C}(D)) \subseteq \Gamma(V,
  \struct{C}(D'))\) and \(B(D) \subseteq B(D')\) induce the twist map
  \(\check{H}^1(D) \to \check{H}^1(D')\), and the inclusions \(L(D)
  \subseteq \Gamma(V, \struct{C}(D))\) induce the \emph{window map}
  \[
    L(D')/L(D) \longrightarrow \Gamma(V, \struct{C}(D'))\big/
      \Gamma(V, \struct{C}(D)),
  \]
  the left-hand map of the four-term ledger sequence of
  \Cref{thm:adelic_twist_exact_sequence}.
\end{definition}

\begin{theorem}
[The window map is injective]
  \label{thm:adelic_windowMap_injective}

  \[
    \bigl(\ell(D') - i(D')\bigr) - \bigl(\ell(D) - i(D)\bigr)
      = \deg(D' - D),
    \qquad\text{i.e.}\qquad \chi(D') - \chi(D) = \deg(D' - D).
  \]
  Every divisor \(D\) satisfies \(D - D_- \le D \le D_+\) with
  \(0 \le D_+\); applying the additivity to \(0 \le D_+\) and to
  \(D \le D + D_-\) and adding, one gets \(\chi(D) = \chi(0) + \deg D\)
  for all \(D\) (additivity of \(\chi - \deg\) as a function on the free
  group of divisors, which agrees at \(0\) and is additive on each unit
  step, hence is \(\chi(0)\) plus the homomorphism \(\deg\)). Finally
  \(\chi(0) = \ell(0) - i(0) = 1 - g\): the global sections
  \(L(0) = \Gamma(U_0, \struct{C}) \cap \Gamma(U_1, \struct{C}) =
  H^0(C, \struct{C})\) equal the constants \(k\), of dimension
  \(\ell(0) = 1\): properness makes the global section ring finite over
  \(k\), while geometric integrality rules out a nontrivial finite
  extension of constants.  Moreover,
  \(i(0)=\dim_k\check H^1_{\mathrm{ff}}(0)=g\) by
  \Cref{thm:adelic_function_field_H1_zero_compare} and
  \cref{thm:adelic_HModuleOne_linearEquiv_cokernel}. Hence
  \(\chi(D) = \deg D + 1 - g\).
\end{proof}

\begin{lemma}
[Nonnegativity of the index of speciality]
  \label{lem:adelic_chi_le_ell}
  \leanok
  \lean{AlgebraicGeometry.Adelic.chi_le_ell}
  \uses{def:adelic_chi_ledger}
  \(\chi(D) \le \ell(D)\), i.e.\ \(h^1(D) = i(D) \ge 0\).
\end{lemma}
\begin{proof}
  \leanok
  Immediate from \(\chi(D) = \ell(D) - h^1(D)\) and \(h^1(D) \ge 0\).
\end{proof}

\begin{lemma}
[The Riemann inequality from a telescoped \(\chi\)]
  \label{lem:adelic_riemann_inequality_conditional}
  \leanok
  \lean{AlgebraicGeometry.Adelic.riemann_inequality}
  \uses{lem:adelic_chi_le_ell}
  Given \(\chi(D) = \chi(0) + \deg D\) (the telescoped Euler
  characteristic of \Cref{thm:adelic_chi_eq_chi_zero_add_degree}),
  \[
    \deg D + \chi(0) \;\le\; \ell(D).
  \]
\end{lemma}
\begin{proof}
  \leanok
  Substitute \(\chi(D) = \chi(0) + \deg D\) into
  \Cref{lem:adelic_chi_le_ell}.
\end{proof}

\begin{corollary}
[Riemann inequality; all \(\check{H}^1(D)\) finite]
  \label{thm:adelic_riemann_inequality}
  \uses{thm:adelic_chi_eq_chi_zero_add_degree, thm:adelic_module_finite_genus, thm:adelic_twist_exact_sequence, thm:adelic_dim_adele_quotient_eq_degree, lem:adelic_riemann_inequality_conditional}
  % [papaioannou] Thm. 1.17 (Riemann inequality deg D - dim D <= g - 1); [cff] Thm. 12.10
  \source{papaioannou-algebraic-rr, cff-curves-function-fields}
  For every Weil divisor \(D\), the space \(\check{H}^1(D)\) is
  finite-dimensional and
  \[
    \deg D + 1 - g \;\le\; \ell(D) .
  \]
\end{corollary}

